#include <benchmark/benchmark.h>

#include <random>
#include <vector>

#include "hogd/container/merkle/hex_array.h"
#include "hogd/container/merkle/merkle_trie.h"

namespace {

constexpr size_t kNumKVPairs = 2'000'000;

// Generates a 64-byte path. Each path generated by this function is unique. The
// last 8 bytes of the path hold a counter value while the remaining bytes hold
// randomly generated values.
hogd::HexArray
generate_64_byte_path()
{
  constexpr size_t kPathNumBytes = 64;
  std::random_device rd;
  std::mt19937 gen(rd());

  static std::vector<std::byte> path(kPathNumBytes);
  static size_t counter = 0;
  std::uniform_int_distribution<int> path_dist(0, 0xff);
  memcpy(path.data() + path.size() - sizeof(counter), &counter,
         sizeof(counter));
  counter++;
  for (size_t i = 0; i < path.size() - sizeof(counter); i++) {
    path[i] = static_cast<std::byte>(path_dist(gen));
  }
  return hogd::HexArray(path);
}

std::vector<hogd::HexArray>
precompute_paths(size_t num_paths)
{
  std::vector<hogd::HexArray> paths;
  paths.reserve(num_paths);
  for (size_t i = 0; i < num_paths; i++) {
    paths.push_back(generate_64_byte_path());
  }
  return paths;
}

} // namespace

// Inserts 2 million KV pairs into a trie. Node hashes are computed on every
// insert operation.
void
insert_two_million(benchmark::State &state)
{
  hogd::MerkleTrie trie;

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (auto _ : state) {
    for (size_t i = 0; i < paths.size(); i++) {
      CHECK(trie.insert(paths[i], "hello"));
    }
  }
}
BENCHMARK(insert_two_million)->Iterations(1)->Unit(benchmark::kSecond);

// Inserts 2 million KV pairs into a trie. Node hashes are *not* computed on
// any insert operations. Rather, the hashes for all nodes are computed once
// after all 2 million KV pairs are inserted.
void
generate_all_hashes_two_million(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (auto _ : state) {
    for (size_t i = 0; i < paths.size(); i++) {
      CHECK(trie.insert(paths[i], "hello"));
    }
    trie.generate_all_hashes();
    trie.set_should_hash_nodes_on_each_op(true);
  }
}
BENCHMARK(generate_all_hashes_two_million)
    ->Iterations(1)
    ->Unit(benchmark::kSecond);

// Inserts 2 million KV pairs into a trie. Just measures the overhead of
// [insert()] operations. Nodes are not hashed at any point--not even at the
// end.
void
insert_two_million_no_hash(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (auto _ : state) {
    for (size_t i = 0; i < paths.size(); i++) {
      CHECK(trie.insert(paths[i], "hello"));
    }
  }
}
BENCHMARK(insert_two_million_no_hash)->Iterations(1)->Unit(benchmark::kSecond);

// Inserts 2 million KV pairs into a trie. Just measures the overhead of
// hashing all nodes once at the end.
void
insert_two_million_hash_once_at_end(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  for (auto _ : state) {
    trie.generate_all_hashes();
  }
}
BENCHMARK(insert_two_million_hash_once_at_end)->Unit(benchmark::kSecond);

namespace {

constexpr size_t kAdditionalPaths = 1'000;

} // namespace

// Inserts 2 million KV pairs into a trie. Measures the overhead of
// incrementally adding additional KV pairs.
void
incremental_insert(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  trie.generate_all_hashes();
  trie.set_should_hash_nodes_on_each_op(true);

  paths = precompute_paths(/*num_paths=*/kAdditionalPaths);
  size_t counter = 0;
  for (auto _ : state) {
    CHECK(trie.insert(paths[counter++], "hello"));
  }
}
BENCHMARK(incremental_insert)
    ->Iterations(kAdditionalPaths)
    ->Unit(benchmark::kMicrosecond);

// Removes 2 million KV pairs from a trie. Nodes are hashed after each
// [remove()] operation.
void
remove_two_million(benchmark::State &state)
{
  hogd::MerkleTrie trie;

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  for (auto _ : state) {
    for (size_t i = 0; i < paths.size(); i++) {
      trie.remove(paths[i]);
    }
  }
}
BENCHMARK(remove_two_million)->Iterations(1)->Unit(benchmark::kSecond);

// Removes 2 million KV pairs from a trie. Nodes are *not* hashed at any point.
void
remove_two_million_no_hash(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  for (auto _ : state) {
    for (size_t i = 0; i < paths.size(); i++) {
      trie.remove(paths[i]);
    }
  }
}
BENCHMARK(remove_two_million_no_hash)->Iterations(1)->Unit(benchmark::kSecond);

// Removes 2 million KV pairs from a trie. Nodes are *not* hashed after each
// [remove()] operation. We just rehash at the end (though the rehash is quick
// since only the root node remains).
void
remove_two_million_hash_once_at_end(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  for (auto _ : state) {
    for (size_t i = 0; i < paths.size(); i++) {
      trie.remove(paths[i]);
    }
    trie.generate_all_hashes();
  }
}
BENCHMARK(remove_two_million_hash_once_at_end)
    ->Iterations(1)
    ->Unit(benchmark::kSecond);

// Finds a single KV pair.
void
find(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  trie.generate_all_hashes();
  trie.set_should_hash_nodes_on_each_op(true);

  for (auto _ : state) {
    CHECK_NE(trie.find(paths[0]), nullptr);
  }
}
BENCHMARK(find);

// Generates a proof for a single KV pair.
void
get_proof(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  trie.generate_all_hashes();
  trie.set_should_hash_nodes_on_each_op(true);

  for (auto _ : state) {
    const auto &pair = trie.get_proof(paths[0]);
    (void)pair;
  }
}
BENCHMARK(get_proof);

// Checks the proof for a single KV pair.
void
prove(benchmark::State &state)
{
  hogd::MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<hogd::HexArray> paths =
      precompute_paths(/*num_paths=*/kNumKVPairs);
  for (size_t i = 0; i < paths.size(); i++) {
    CHECK(trie.insert(paths[i], "hello"));
  }
  trie.generate_all_hashes();
  trie.set_should_hash_nodes_on_each_op(true);

  const auto &pair = trie.get_proof(paths[0]);
  for (auto _ : state) {
    CHECK(trie.prove(pair.first, pair.second, paths[0], "hello"));
  }
}
BENCHMARK(prove);

BENCHMARK_MAIN();
